class BatchSendStatusType(enum.Enum):
    IN_PROGRESS = 0
    
    SUCCEEDED = 1
    
    DISCARDED = 2
    


class _UniffiConverterTypeBatchSendStatusType(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return BatchSendStatusType.IN_PROGRESS
        if variant == 2:
            return BatchSendStatusType.SUCCEEDED
        if variant == 3:
            return BatchSendStatusType.DISCARDED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == BatchSendStatusType.IN_PROGRESS:
            return
        if value == BatchSendStatusType.SUCCEEDED:
            return
        if value == BatchSendStatusType.DISCARDED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == BatchSendStatusType.IN_PROGRESS:
            buf.write_i32(1)
        if value == BatchSendStatusType.SUCCEEDED:
            buf.write_i32(2)
        if value == BatchSendStatusType.DISCARDED:
            buf.write_i32(3)







class CommandArgumentError:
    """
    An error with an argument to a command

    # BCS

    The BCS serialized form for this type is defined by the following ABNF:

    ```text
    command-argument-error =  type-mismatch
    =/ invalid-bcs-bytes
    =/ invalid-usage-of-pure-argument
    =/ invalid-argument-to-private-entry-function
    =/ index-out-of-bounds
    =/ secondary-index-out-of-bound
    =/ invalid-result-arity
    =/ invalid-gas-coin-usage
    =/ invalid-value-usage
    =/ invalid-object-by-value
    =/ invalid-object-by-mut-ref
    =/ shared-object-operation-not-allowed

    type-mismatch                               = %d00
    invalid-bcs-bytes                           = %d01
    invalid-usage-of-pure-argument              = %d02
    invalid-argument-to-private-entry-function  = %d03
    index-out-of-bounds                         = %d04 u16
    secondary-index-out-of-bound                = %d05 u16 u16
    invalid-result-arity                        = %d06 u16
    invalid-gas-coin-usage                      = %d07
    invalid-value-usage                         = %d08
    invalid-object-by-value                     = %d09
    invalid-object-by-mut-ref                   = %d10
    shared-object-operation-not-allowed         = %d11
    ```
    """

    def __init__(self):
        raise RuntimeError("CommandArgumentError cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class TYPE_MISMATCH:
        """
        The type of the value does not match the expected type
        """


        def __init__(self,):
            pass

        def __str__(self):
            return "CommandArgumentError.TYPE_MISMATCH()".format()

        def __eq__(self, other):
            if not other.is_TYPE_MISMATCH():
                return False
            return True
    
