        if value == SignatureScheme.SECP256K1:
            return
        if value == SignatureScheme.SECP256R1:
            return
        if value == SignatureScheme.MULTISIG:
            return
        if value == SignatureScheme.BLS12381:
            return
        if value == SignatureScheme.ZK_LOGIN_AUTHENTICATOR_DEPRECATED:
            return
        if value == SignatureScheme.PASSKEY_AUTHENTICATOR:
            return
        if value == SignatureScheme.MOVE_AUTHENTICATOR:
            return
        raise ValueError(value)

